Qed.

Lemma iarm_rhs_0RB1LA_1LC1RC_1RD0LA_1RB0LA : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  lr_rhs (iarm_0RB1LA_1LC1RC_1RD0LA_1RB0LA d r)
