Lemma farm_rhs_0RB1LA_1RC1RD_1LC0LA_1RB1RC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_rhs (farm_0RB1LA_1RC1RD_1LC0LA_1RB1RC r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_0RB1LA_1RC1RD_1LC0LA_1RB1RC r ph)
                      (astride 1 1 r) (fm2_0RB1LA_1RC1RD_1LC0LA_1RB1RC r ph)
