Theorem nqhtr_0RB1LC_0LC1RB_1LA0LD_1RA1RA : NeverQuasiHaltsTr tm_0RB1LC_0LC1RB_1LA0LD_1RA1RA.
Proof.
  eapply (boardN_neverqhtr tm_0RB1LC_0LC1RB_1LA0LD_1RA1RA pins_0RB1LC_0LC1RB_1LA0LD_1RA1RA FAM 2
                           iarm_0RB1LC_0LC1RB_1LA0LD_1RA1RA 1 1
