Lemma bootl_0RB1LD_1RC1RB_1LA0LD_0RC0LD :
  stepn tm 25 InitES = Some (lift (fam_cfg FAM ([0], 0, 1))).
Proof.
  assert (H : match csteps tm 25 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 1))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 25 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_0RB1LD_1RC1RB_1LA0LD_0RC0LD : NeverQuasiHaltsTr tm_0RB1LD_1RC1RB_1LA0LD_0RC0LD.
Proof.
  eapply (boardN_neverqhtr tm_0RB1LD_1RC1RB_1LA0LD_0RC0LD pins_0RB1LD_1RC1RB_1LA0LD_0RC0LD FAM 2
                           iarm_0RB1LD_1RC1RB_1LA0LD_0RC0LD 0 1
                           farm_0RB1LD_1RC1RB_1LA0LD_0RC0LD 1 1
                           fm1_0RB1LD_1RC1RB_1LA0LD_0RC0LD fm2_0RB1LD_1RC1RB_1LA0LD_0RC0LD 0
                           nrules vsegs_0RB1LD_1RC1RB_1LA0LD_0RC0LD vis_0RB1LD_1RC1RB_1LA0LD_0RC0LD
                           [0] 1).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 1; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_0RB1LD_1RC1RB_1LA0LD_0RC0LD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
