Definition pins_1RB0LC_0RC1RA_0RD1LC_1LD1RB : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB0LC_0RC1RA_0RD1LC_1LD1RB pins_1RB0LC_0RC1RA_0RD1LC_1LD1RB).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0LC_0RC1RA_0RD1LC_1LD1RB : Fam := mkFam 2 [[S1;S1];[S1;S0]] [] [[]] Binary 1 [mkFill 2 [] 0 [1;1] 0] StD S1 false [].
Local Notation FAM := fam_1RB0LC_0RC1RA_0RD1LC_1LD1RB.

(** ** The ladder, as DATA

    4 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0LC_0RC1RA_0RD1LC_1LD1RB : list (LRule * list rstep) :=
  [(mkLRule (mkC StC (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StA (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StA (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StA (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB0LC_0RC1RA_0RD1LC_1LD1RB.

Definition rules_1RB0LC_0RC1RA_0RD1LC_1LD1RB : list LRule := map fst lad.
Local Notation rules := rules_1RB0LC_0RC1RA_0RD1LC_1LD1RB.

Lemma ladder_ok_1RB0LC_0RC1RA_0RD1LC_1LD1RB : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LC_0RC1RA_0RD1LC_1LD1RB : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LC_0RC1RA_0RD1LC_1LD1RB. Qed.

