Lemma bootl_1RB0LC_1LC1RD_0RA1LC_1RB1RA :
  stepn tm 13 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm 13 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 13 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB0LC_1LC1RD_0RA1LC_1RB1RA : NeverQuasiHaltsTr tm_1RB0LC_1LC1RD_0RA1LC_1RB1RA.
Proof.
  eapply (boardN_neverqhtr tm_1RB0LC_1LC1RD_0RA1LC_1RB1RA pins_1RB0LC_1LC1RD_0RA1LC_1RB1RA FAM 4
                           iarm_1RB0LC_1LC1RD_0RA1LC_1RB1RA 1 1
                           farm_1RB0LC_1LC1RD_0RA1LC_1RB1RA 1 1
                           fm1_1RB0LC_1LC1RD_0RA1LC_1RB1RA fm2_1RB0LC_1LC1RD_0RA1LC_1RB1RA 2
                           nrules vsegs_1RB0LC_1LC1RD_0RA1LC_1RB1RA vis_1RB0LC_1LC1RD_0RA1LC_1RB1RA
                           [0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 3; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 2; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    destruct ph as [|ph].
