  | StD, S1 => mk S1 DL StC
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB0RC_0LC1RA_0RA1LD_0LC1LC : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB0RC_0LC1RA_0RA1LD_0LC1LC pins_1RB0RC_0LC1RA_0RA1LD_0LC1LC).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0RC_0LC1RA_0RA1LD_0LC1LC : Fam := mkFam 2 [[S1;S1];[S0;S1]] [] [[]] Binary 1 [mkFill 1 [1] 0 [] 0] StC S0 false [].
Local Notation FAM := fam_1RB0RC_0LC1RA_0RA1LD_0LC1LC.

(** ** The ladder, as DATA

    6 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0RC_0LC1RA_0RA1LD_0LC1LC : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StB (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StD (mkS [S1;S1;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1;S1;S1] [] 0 0 [])) 0 4, [RB (SWin 4)]);
   (mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB0RC_0LC1RA_0RA1LD_0LC1LC.

Definition rules_1RB0RC_0LC1RA_0RA1LD_0LC1LC : list LRule := map fst lad.
Local Notation rules := rules_1RB0RC_0LC1RA_0RA1LD_0LC1LC.

Lemma ladder_ok_1RB0RC_0LC1RA_0RA1LD_0LC1LC : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0RC_0LC1RA_0RA1LD_0LC1LC : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0RC_0LC1RA_0RA1LD_0LC1LC. Qed.

