Lemma ladder_ok_1RB0RD_0LC1RA_0RA1LC_1LA1LB : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0RD_0LC1RA_0RA1LC_1LA1LB : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0RD_0LC1RA_0RA1LC_1LA1LB. Qed.

