Lemma nrules_sound_1RB0RD_0LC1RA_0RA1LC_1LA1LB : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB0RD_0LC1RA_0RA1LC_1LA1LB. Qed.

