Lemma bootl_1RB1LB_1LC1RC_1RA0LD_0RB1LD :
  stepn tm 10 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
Proof.
  assert (H : match csteps tm 10 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 10 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB1LB_1LC1RC_1RA0LD_0RB1LD : NeverQuasiHaltsTr tm_1RB1LB_1LC1RC_1RA0LD_0RB1LD.
Proof.
  eapply (boardN_neverqhtr tm_1RB1LB_1LC1RC_1RA0LD_0RB1LD pins_1RB1LB_1LC1RC_1RA0LD_0RB1LD FAM 1
                           iarm_1RB1LB_1LC1RC_1RA0LD_0RB1LD 0 1
                           farm_1RB1LB_1LC1RC_1RA0LD_0RB1LD 2 1
                           fm1_1RB1LB_1LC1RC_1RA0LD_0RB1LD fm2_1RB1LB_1LC1RC_1RA0LD_0RB1LD 0
                           nrules vsegs_1RB1LB_1LC1RC_1RA0LD_0RB1LD vis_1RB1LB_1LC1RC_1RA0LD_0RB1LD
                           [1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
