Lemma fm12_1RB1LC_1LA0RD_1RD1LB_0LA1RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 ->
  fm1_1RB1LC_1LA0RD_1RD1LB_0LA1RD r ph + fm2_1RB1LC_1LA0RD_1RD1LB_0LA1RD r ph
  + (length (f_pre (fam_fill FAM ph)) + length (f_suf (fam_fill FAM ph)))
